mapper.insert:
INSERT INTO fba_shipment (
    fba_shipment_id, tenant_id, amazon_shipment_id, destination_fc, plan_id, carrier,
    tracking_no, planned_quantity, received_quantity, carton_count, total_weight, status,
    packed_at, shipped_at, created_at, updated_at
) VALUES (
    #{fbaShipmentId}, #{tenantId}, #{amazonShipmentId}, #{destinationFc}, #{planId}, #{carrier},
    #{trackingNo}, #{plannedQuantity}, #{receivedQuantity}, #{cartonCount}, #{totalWeight}, #{status},
    #{packedAt}, #{shippedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT fba_shipment_id, tenant_id, amazon_shipment_id, destination_fc, plan_id, carrier,
       tracking_no, planned_quantity, received_quantity, carton_count, total_weight, status,
       packed_at, shipped_at, created_at, updated_at
FROM fba_shipment
WHERE tenant_id = #{tenantId}
  AND fba_shipment_id = #{fbaShipmentId}

SELECT fba_shipment_id, tenant_id, amazon_shipment_id, destination_fc, plan_id, carrier,
       tracking_no, planned_quantity, received_quantity, carton_count, total_weight, status,
       packed_at, shipped_at, created_at, updated_at
FROM fba_shipment
WHERE tenant_id = #{tenantId}
  AND amazon_shipment_id = #{amazonShipmentId}

SELECT fba_shipment_id, tenant_id, amazon_shipment_id, destination_fc, plan_id, carrier, tracking_no, planned_quantity, received_quantity, carton_count, total_weight, status, packed_at, shipped_at, created_at, updated_at FROM fba_shipment WHERE tenant_id = #{tenantId}
AND plan_id = #{planId}
ORDER BY created_at DESC

