INSERT INTO fba_inventory (
    inventory_id, tenant_id, warehouse_id, product_id, seller_sku, fnsku,
    quantity, store_id, site_code, inventory_age_days, last_updated
) VALUES (
    #{inventoryId}, #{tenantId}, #{warehouseId}, #{productId}, #{sellerSku}, #{fnsku},
    #{quantity}, #{storeId}, #{siteCode}, #{inventoryAgeDays}, #{lastUpdated}
)

mapper.select:
SELECT inventory_id, tenant_id, warehouse_id, product_id, seller_sku, fnsku,
       quantity, store_id, site_code, inventory_age_days, last_updated
FROM fba_inventory
WHERE tenant_id = #{tenantId}
  AND inventory_id = #{inventoryId}

SELECT inventory_id, tenant_id, warehouse_id, product_id, seller_sku, fnsku,
       quantity, store_id, site_code, inventory_age_days, last_updated
FROM fba_inventory
WHERE tenant_id = #{tenantId}
  AND warehouse_id = #{warehouseId}
  AND seller_sku = #{sellerSku}


          AND fnsku = #{fnsku}


          AND (fnsku IS NULL OR fnsku = '')




          AND store_id = #{storeId}


          AND (store_id IS NULL OR store_id = '')




          AND site_code = #{siteCode}


          AND (site_code IS NULL OR site_code = '')

SELECT inventory_id, tenant_id, warehouse_id, product_id, seller_sku, fnsku,
       quantity, store_id, site_code, inventory_age_days, last_updated
FROM fba_inventory
WHERE tenant_id = #{tenantId}

    AND seller_sku = #{sellerSku}


    AND store_id = #{storeId}


    AND site_code = #{siteCode}


    AND warehouse_id = #{warehouseId}

ORDER BY last_updated DESC, seller_sku ASC

