SET seller_sku = #{sellerSku},
    destination_fc = #{destinationFc},
    suggested_quantity = #{suggestedQuantity},
    source_warehouse_id = #{sourceWarehouseId},
    status = #{status},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND plan_id = #{planId}

